styles:
.b-press-logos {
    container-type: inline-size;
}

.b-press-logos__title {
    margin: 0 0 1em;
    text-align: center;
}

/* As many across as fit at 8em each: a strip on a wide page, a grid on a phone. */
.b-press-logos__list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(8em, 1fr));
    gap: 1.5em 2em;
    align-items: center;
    margin: 0;
    padding: 0;
    list-style: none;
}

/* A grid or flex box outranks the browser's own [hidden] rule. */
.b-press-logos__list[hidden],
.b-press-logos__link[hidden] {
    display: none;
}

.b-press-logos__item {
    min-width: 0;
}

.b-press-logos__link {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 3em;
    color: inherit;
    text-decoration: none;
}

/* Logos come in every shape: held to one height, never wider than their cell. */
.b-press-logos__logo {
    display: block;
    width: auto;
    max-width: 100%;
    min-width: 0;
    height: auto;
    max-height: 3em;
    object-fit: contain;
    opacity: 0.75;
    transition: opacity 0.2s;
}

.b-press-logos__link:hover .b-press-logos__logo,
.b-press-logos__link:focus-visible .b-press-logos__logo {
    opacity: 1;
}

.b-press-logos__name {
    font-weight: 600;
    text-align: center;
}
